import path from 'node:path';

const DATA_DIR = path.resolve('data');

// Resolve a user-supplied path against the data directory and ensure the
// result stays inside it. Returns the resolved absolute path or null when the
// path escapes the data directory (traversal or absolute path).
function resolveSafe(target) {
  if (path.isAbsolute(target)) return null;
  const resolved = path.resolve(DATA_DIR, target);
  const rel = path.relative(DATA_DIR, resolved);
  if (rel === '') return resolved; // the data directory itself
  if (rel.startsWith('..') || path.isAbsolute(rel)) return null;
  return resolved;
}

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description:
        'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. File contents are never exposed.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path of the file within the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }

  const argv = args || {};
  const allowed = new Set(['path']);
  for (const key of Object.keys(argv)) {
    if (!allowed.has(key)) {
      throw new Error('Unexpected argument: ' + key);
    }
  }

  const target = argv.path;
  if (typeof target !== 'string' || target.length === 0) {
    throw new Error('Invalid arguments: "path" is required and must be a non-empty string');
  }

  const resolved = resolveSafe(target);
  if (!resolved) {
    throw new Error('Invalid path: traversal outside the data directory is not allowed');
  }

  let stat;
  try {
    stat = await fs.promises.stat(resolved);
  } catch (_e) {
    throw new Error('File not found: ' + target);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + target);
  }

  const rel = path.relative(DATA_DIR, resolved);
  const ext = path.extname(rel).toLowerCase();
  const size = stat.size;
  const text = `path: ${rel}\nsize: ${size} bytes\nextension: ${ext}`;

  return {
    content: [{ type: 'text', text }]
  };
}

