+// path escapes the data directory (traversal or absolute path).
+function resolveSafe(target) {
+  if (path.isAbsolute(target)) return null;
+  const resolved = path.resolve(DATA_DIR, target);
+  const rel = path.relative(DATA_DIR, resolved);
+  if (rel === '') return resolved; // the data directory itself
+  if (rel.startsWith('..') || path.isAbsolute(rel)) return null;
+  return resolved;
